//! Values derived from the CMU Pronouncing Dictionary (CMUdict, BSD-2-Clause-style; see NOTICE
//! and `style/data/licenses/cmudict.txt`). Only derived values are bundled: syllable counts and
//! each word's first phoneme, never whole pronunciations. Each table is generated by
//! `scripts/build-cmudict.py` from one pinned `cmudict.dict`, and each keeps only the words a
//! spelling heuristic here or in the readability report gets wrong.

use std::collections::HashMap;
use std::sync::OnceLock;

const SYLLABLES: &str = include_str!("../data/pronunciation/cmudict-syllables.tsv");
const ONSETS: &str = include_str!("../data/pronunciation/cmudict-onsets.tsv");

fn syllable_table() -> &'static HashMap<&'static str, usize> {
    static TABLE: OnceLock<HashMap<&'static str, usize>> = OnceLock::new();
    TABLE.get_or_init(|| {
        SYLLABLES
            .lines()
            .filter(|line| !line.starts_with('#'))
            .filter_map(|line| {
                let (word, count) = line.split_once('\t')?;
                Some((word, count.parse().ok()?))
            })
            .collect()
    })
}

/// CMUdict's syllable count (first pronunciation) for a key the heuristic in
/// [`crate::reports::readability::syllables`] gets wrong, or `None`. The table holds only those
/// exceptions: with it, every CMUdict headword gets CMUdict's count from
/// [`crate::reports::readability::syllables_with`]. A `None` therefore does not mean the word is
/// missing from CMUdict. Keys are lowercase with straight apostrophes and no leading or trailing
/// punctuation (`u.s`, `didn't`).
pub fn syllable_exception(key: &str) -> Option<usize> {
    syllable_table().get(key).copied()
}

/// Number of keys in the bundled syllable table.
pub fn syllable_exception_count() -> usize {
    syllable_table().len()
}

fn onset_table() -> &'static HashMap<&'static str, &'static str> {
    static TABLE: OnceLock<HashMap<&'static str, &'static str>> = OnceLock::new();
    TABLE.get_or_init(|| {
        ONSETS
            .lines()
            .filter(|line| !line.starts_with('#'))
            .filter_map(|line| line.split_once('\t'))
            .collect()
    })
}

/// CMUdict's first phoneme (first pronunciation) for a key [`spelled_onset`] gets wrong, or
/// `None`. Like [`syllable_exception`], the table holds only those exceptions, so a `None` does
/// not mean the word is missing from CMUdict. Values are the labels [`spelled_onset`] returns.
pub fn onset_exception(key: &str) -> Option<&'static str> {
    onset_table().get(key).copied()
}

/// Number of keys in the bundled onset table.
pub fn onset_exception_count() -> usize {
    onset_table().len()
}

/// The consonant labels [`initial_sound`] returns: lowercase ARPAbet, so `jh` is the sound of
/// *j* in *jam* and *g* in *gem*, `dh` is *th* in *then*, `hh` is *h*, and `zh` is the *s* in
/// *measure*.
pub const CONSONANTS: [&str; 24] = [
    "b", "ch", "d", "dh", "f", "g", "hh", "jh", "k", "l", "m", "n", "ng", "p", "r", "s", "sh", "t",
    "th", "v", "w", "y", "z", "zh",
];

/// A word's first phoneme guessed from its spelling: a consonant label from [`CONSONANTS`], or
/// `"-"` for a vowel. `key` is lowercase with straight apostrophes, as for [`onset_exception`].
pub fn spelled_onset(key: &str) -> &'static str {
    let word = key.trim_start_matches(|c: char| !c.is_alphabetic());
    // Loanwords keep their accents (`élan`, `Über`). An accented vowel is a vowel sound (never
    // the glide of `unit`); other common Latin letters fold to their base letter, `ç` always soft.
    if word.starts_with(|c: char| "àáâãäåāèéêëēìíîïīòóôõöøōùúûüū".contains(c))
    {
        return "-";
    }
    let word: String = word
        .chars()
        .map(|c| match c {
            'à' | 'á' | 'â' | 'ã' | 'ä' | 'å' | 'ā' => 'a',
            'è' | 'é' | 'ê' | 'ë' | 'ē' => 'e',
            'ì' | 'í' | 'î' | 'ï' | 'ī' => 'i',
            'ò' | 'ó' | 'ô' | 'õ' | 'ö' | 'ø' | 'ō' => 'o',
            'ù' | 'ú' | 'û' | 'ü' | 'ū' => 'u',
            'ç' => 's',
            'ñ' => 'n',
            'ý' | 'ÿ' => 'y',
            c => c,
        })
        .collect();
    let word = word.as_str();
    let next = |at: usize| word.as_bytes().get(at).copied().unwrap_or(b' ');
    let vowel = |c: u8| b"aeiou".contains(&c);
    const DIGRAPHS: [(&str, &str); 16] = [
        ("sch", "sh"),
        ("chr", "k"),
        ("chl", "k"),
        ("ch", "ch"),
        ("sh", "sh"),
        ("th", "th"),
        ("ph", "f"),
        ("wh", "w"),
        ("wr", "r"),
        ("kn", "n"),
        ("gn", "n"),
        ("ps", "s"),
        ("pn", "n"),
        ("rh", "r"),
        ("gh", "g"),
        ("qu", "k"),
    ];
    if let Some((_, sound)) = DIGRAPHS.iter().find(|(start, _)| word.starts_with(start)) {
        return sound;
    }
    match next(0) {
        b'c' if b"eiy".contains(&next(1)) => "s",
        b'c' | b'k' | b'q' => "k",
        // `gem`, `gym`, but `give`: a soft g before e and y, a hard one before i.
        b'g' if b"ey".contains(&next(1)) => "jh",
        b'j' => "jh",
        b'h' => "hh",
        b'x' => "z",
        b'y' if vowel(next(1)) => "y",
        b'y' => "-",
        _ if word.starts_with("eu") || word.starts_with("ewe") => "y",
        _ if word.starts_with("one") || word.starts_with("once") => "w",
        // `unit`, `use`, `usual`, but `unable`, `under`, `ugly`.
        b'u' if !vowel(next(1))
            && b"aeiouy".contains(&next(2))
            && (!word.starts_with("un") || word.starts_with("uni")) =>
        {
            "y"
        }
        c if vowel(c) || !c.is_ascii_alphabetic() => "-",
        c => CONSONANTS
            .iter()
            .find(|label| label.as_bytes() == [c])
            .copied()
            .unwrap_or("-"),
    }
}

/// The first phoneme of a word as written in text, asking `lookup` first. The word is folded to
/// a key (lowercase, straight apostrophes, no leading or trailing punctuation); the whole key is
/// tried, then the part before the first hyphen, then the stem before an apostrophe (`ahab` in
/// `Ahab’s`), then the spelling. Returns a [`CONSONANTS`] label or `"-"` for a vowel.
pub fn initial_sound_with<'a>(word: &str, lookup: &dyn Fn(&str) -> Option<&'a str>) -> &'a str {
    let key: String = word
        .chars()
        .map(|c| if c == '’' { '\'' } else { c })
        .flat_map(char::to_lowercase)
        .collect();
    let key = key.trim_matches(|c: char| !c.is_alphanumeric());
    let first = key.split(crate::reports::HYPHENS).next().unwrap_or(key);
    let stem = first.split('\'').next().unwrap_or(first);
    lookup(key)
        .or_else(|| lookup(first))
        .or_else(|| lookup(stem))
        .unwrap_or_else(|| spelled_onset(key))
}

/// The first phoneme of a word as written in text, from the bundled table with the spelling as
/// fallback. See [`initial_sound_with`].
pub fn initial_sound(word: &str) -> &'static str {
    initial_sound_with(word, &onset_exception)
}
